{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "Imidafenacin absolute oral bioavailability was 57.8% (95% CI 54.1–61.4) in healthy subjects after a single 0.1 mg oral dose, well above the 20% threshold."
    },
    {
      "card_ids": ["C34"],
      "claim": "Tolvaptan mean absolute oral bioavailability was 56% (range 42–80%) in healthy subjects after a 30 mg oral tablet versus IV, supporting high bioavailability."
    },
    {
      "card_ids": ["C20"],
      "claim": "One fasting-volunteer record reported aspirin (ASA) availability of about 17%, below the 20% threshold; this is an outlier within a mixed aspirin/salicylate record set and is outweighed by multiple complete or near-complete salicylate bioavailability records."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": ["C20"],
  "decision_summary": "High is predicted because multiple direct absolute oral bioavailability measurements in humans are 53–86%, all above the 20% threshold; the single sub-threshold fasting ASA record (C20) is an outlier in a mixed aspirin/salicylate set and does not overturn the consistent high-availability evidence.",
  "evidence_gaps": [
    "Molecule 2 has a provenance/analyte conflict: C20 reports ~17% ASA availability while other records report complete/near-complete salicylate bioavailability; the identity/analyte difference is not resolved.",
    "Several records are qualitative ('good', 'not good') or predicted rather than measured absolute F, so they are not used as threshold-specific evidence.",
    "Fasted-state conditions are explicitly stated only in C20; most high-F records do not specify prandial state, though assay-transfer scores are high."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C22", "C34"],
  "revision_action": "initial",
  "supportive_card_ids": ["C22", "C34"]
}

